	// overlay so reads observe the transaction's earlier writes, then
	// commit the final value of every written key to the store in one go.
	// Nothing outside this critical section can observe the store while
	// we hold the lock, so intermediate values are never visible.
	overlay := make(map[string]string, len(mops))
	for _, m := range mops {
		if m.f == "w" {
			overlay[m.k] = m.v
		}
	}

