		writes := make([]writeOp, 0, len(overlay))
		for k, v := range overlay {
			writes = append(writes, writeOp{K: json.RawMessage(k), V: json.RawMessage(v)})
		}
		s.log = append(s.log, txnRec{Seq: int64(len(s.log)), Writes: writes})
	}

