	out := make([]json.RawMessage, len(mops))
	for i, m := range mops {
		val := ""
		switch {
		case m.f == "w":
			val = m.v // writes are echoed as sent
		default:
			if v, ok := overlay[m.k]; ok {
				val = v // read our own earlier write
			} else if v, ok := s.store[m.k]; ok {
